#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    int best = 1;
    for (size_t i = 0; i < edges.size(); i++) {
        if (unite((int)edges[i][0], (int)edges[i][1])) best = max(best, sizes[findRoot((int)edges[i][0])]);
        cout << (i ? " " : "") << best;
    }
    cout << "\n";

    return 0;
}

