import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int people = (int) n;
        parent = new int[people + 1];
        sizes = new int[people + 1];
        for (int v = 0; v <= people; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        int best = 1;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < edges.length; i++) {
            if (unite((int) edges[i][0], (int) edges[i][1])) best = Math.max(best, sizes[findRoot((int) edges[i][0])]);
            out.append(i > 0 ? " " : "").append(best);
        }
        System.out.println(out);
    }
}
